#!/usr/bin/env bash
# 療育カリキュラム管理 v2.3 / 既存Dockerのみ更新する安全なインストーラー
# 配布ZIPを内蔵。暗号化キー・SQLite DB・個人情報は同梱しない。
set -Eeuo pipefail
umask 077
EXPECTED_SHA256="0d9bc3f18068cd3c95dc0391307c5a3eef0d8aa560d0f3e65813a41fa33d0451"
usage() {
cat <<'HELP'
使い方：
  bash update-ryoiku-v2.3.sh --verify         # 配布ファイル検証（sudo不要）
  sudo bash update-ryoiku-v2.3.sh --check    # 現行Docker導入先を調査（変更なし）
  sudo bash update-ryoiku-v2.3.sh --apply    # バックアップ → 更新 → Docker再ビルド・起動

必要：既存v2.2がDocker Composeで稼働、Docker/Compose、tar、curl、unzip、base64、sha256sum。
注意：新規インストール用ではありません。既存のTailscale Serveやほかのコンテナは変更しません。
      データと .env は絶対に上書きせず、更新時は療育アプリだけ一時停止します。
HELP
}
fail(){ printf 'エラー: %s\n' "$*" >&2; exit 1; }
mode="${1:---check}"
case "$mode" in
  --help|-h) usage;exit 0;;
  --verify|--check|--apply) ;;
  *) usage >&2;exit 2;;
esac
for c in base64 sha256sum unzip mktemp tar; do
  command -v "$c" >/dev/null 2>&1 || fail "$c がありません。sudo apt install unzip などで準備してください。"
done
TMP="$(mktemp -d)"
cleanup(){ rm -rf "$TMP"; }
trap cleanup EXIT
base64 -d >"$TMP/app.zip" <<'RYOIKU_B64'
